exercises.solution:
def compter_seuil(valeurs, seuil):
    nombre = 0
    for valeur in valeurs:
        if valeur >= seuil:
            nombre = nombre + 1
    return nombre

def contient(valeurs, cible):
    for valeur in valeurs:
        if valeur == cible:
            return True
    return False

def somme_positifs(valeurs):
    total = 0
    for valeur in valeurs:
        if valeur > 0:
            total = total + valeur
    return total

def bilan_seuil(valeurs, seuil):
    total = 0
    nombre = 0
    for valeur in valeurs:
        if valeur >= seuil:
            total = total + valeur
            nombre = nombre + 1
    return (total, nombre)
